# Fix the nearest search function
def find_nearest_non6(grid, r, c):
    best = None
    best_dist = float('inf')

    # Up: r-1, r-2, ... until 0
    for dr in range(-1, -r-1, -1):
        nr = r + dr
        if nr < 0:
            continue
        val = grid[nr][c]
        dist = abs(nr - r) + abs(0 - c)  # Manhattan distance from top of block
        if val != 6 and dist < best_dist:
            best_dist = dist
            best = ('U', nr, val)

    # Down: r+1, r+2, ... until 29
    for dr in range(1, 29-r, 1):
        nr = r + dr
        if nr >= 30:
            break
        val = grid[nr][c]
        dist = abs(nr - r) + abs(0 - c)
        if val != 6 and dist < best_dist:
            best_dist = dist
            best = ('D', nr, val)

    # Left: c-1, c-2, ... until 0
    for dc in range(-1, -c-1, -1):
        nc = c + dc
        if nc < 0:
            continue
        val = grid[r][nc]
        dist = abs(0 - r) + abs(nc - c)
        if val != 6 and dist < best_dist:
            best_dist = dist
            best = ('L', nc, val)

    # Right: c+1, c+2, ... until 29
    for dc in range(1, 29-c, 1):
        nc = c + dc
        if nc >= 30:
            break
        val = grid[r][nc]
        dist = abs(0 - r) + abs(nc - c)
        if val != 6 and dist < best_dist:
            best_dist = dist
            best = ('R', nc, val)

    return best

